+			if err := s.Tick(context.Background()); err != nil {
+				t.Fatal(err)
+			}
+			if len(s.MergeQueue) != 0 || f.puts != 0 || len(f.linear.bodies) != 0 {
+				t.Fatalf("unmerged cancellation advanced: queue=%v puts=%d bodies=%v", s.MergeQueue, f.puts, f.linear.bodies)
+			}
+		})
+	}
+}

